/// The running build number, for the front door's headless update lane
/// (`aterm update …` and the session-mode background check in `crates/aterm`) —
/// the value the window entry hands `aterm_update`.
#[must_use]
pub fn running_build_number() -> u64 {
    build_info::build_number().parse::<u64>().unwrap_or(0)
}

pub use update_words::DevSharedWrites;

/// Where THIS copy runs from, for Settings ▸ Software Update's "can't update itself"
/// detail: one path read before the event loop runs. `None` off macOS, and in a unit
/// test, whose binary's location says nothing about the page under test.
fn running_install_posture() -> Option<aterm_update::which_copy::InstallPosture> {
    #[cfg(all(target_os = "macos", not(test)))]
    {
        aterm_update::which_copy::running_posture()
    }
    #[cfg(not(all(target_os = "macos", not(test))))]
    {
        None
    }
}

/// What THIS copy writes of the shared user state only the release writes unattended —
/// the PATH links and shell hooks (its ALab tools passes, when `[packages] enabled` and
/// an `atpkg` sits beside it) and the agent primer (`agents_auto_prime`) — in words with
/// the release's verbs that put it back, or `None` when it writes none of it: every
/// bundle but one NAMED `aterm.app` stands those writers down
/// (`atpkg::hooks::runs_from_non_release_bundle`). A few small reads, done before the
/// event loop runs or off it: a dev build says it (`aterm update status`, and the
/// window's row when it starts; gap #30).
#[must_use]
pub fn dev_build_shared_writes() -> Option<DevSharedWrites> {
    update_words::dev_shared_writes(
        atpkg::hooks::runs_from_non_release_bundle(),
        co_located_atpkg().is_some() && atpkg::config::load().enabled(),
        app_config::agents_auto_prime_setting(),
    )
}

/// Read-only compiled identity for the native updater and release worker. This
/// does not resolve an installation, enroll updates, read config, or open a UI.
#[must_use]
pub fn running_binary_identity() -> aterm_update_core::linux::BinaryIdentity {
    aterm_update_core::linux::BinaryIdentity {
        schema: 1,
        version: build_info::version().into(),
        build_number: running_build_number(),
        commit: build_info::git_commit_full().into(),
        target: build_info::BINARY_TARGET.into(),
        dirty: build_info::git_dirty() == "true",
    }
}

/// The window's `aterm.log` for the terminal session (`aterm --session` in
/// `crates/aterm`), whose background threads — the update check, the reroute lay, the
/// detached-pass spawns — must log rather than print into the shell beside them. The file
/// logger only; the window keeps its own [`main_entry`] setup.
pub fn install_session_log() {
    logging::init_session();
}

/// Persisted source and apply policy for CLI checks and interactive sessions.
#[must_use]
pub fn configured_update_settings() -> Option<aterm_update::CheckSettings> {
    app_config::update_check_settings_setting()
}
