    /// Rows the active overlay (Settings, About, or the command Palette — mutually exclusive) occupies in the
    /// composed frame: the single source the shared splice consults. `0` when none is open.
    /// Dispatches through the [`crate::overlay::OverlayModel`] trait (exhaustive — a missing
    /// variant is a compile error), preserving the min-with-available-rows clamp.
    fn overlay_rows(&self) -> usize {
        self.overlay_rows_with_available(self.input_scratch.cells.len())
    }

    /// Resolve the active overlay height against the exact surface that will
    /// rasterize it. Terminal callers use the composed-frame height; native
    /// callers pass the content-row height below the tab strip.
    fn overlay_rows_with_available(&self, available: usize) -> usize {
        self.overlay
            .as_ref()
            .map_or(0, |o| o.model().wanted_rows(available))
    }

    /// The active overlay's repaint fingerprint (folded into `RepaintKey::settings_fp`);
    /// `0` (the closed sentinel) when no overlay is open. Discriminant-seeded so two
    /// surfaces can never collide in the `settings_card` fp cache.
    fn overlay_fp(&self) -> u64 {
        self.overlay
            .as_ref()
            .map_or(0, crate::overlay::Overlay::fingerprint)
    }

    /// The active overlay slot (any variant), for the `controls front` status read. The
    /// method name intentionally shadows the `overlay` field (both are legal Rust).
    fn overlay(&self) -> Option<&crate::overlay::Overlay> {
        self.overlay.as_ref()
    }

    /// Whether any modal overlay (Settings, About, or the command Palette) is open — the input gate + the sacred
    /// bell-invert / drop-overlay suppression consult this.
    fn overlay_open(&self) -> bool {
        self.overlay.is_some()
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "terminal window creation supplies one capability plus rows/cols and both canonical/compatibility tab projections"
    )]
    fn new_terminal(
        term: Arc<Mutex<Terminal>>,
        master: i32,
        sink: Arc<SinkWriter>,
        ui_waiting: Arc<std::sync::atomic::AtomicU32>,
        session: u64,
        rows: u16,
        cols: u16,
        metrics: MetricsView,
        tabs: TabIndex,
        layouts: Vec<pane::PaneTree>,
        tab_set: tab_model::TabSet,
    ) -> Self {
        let initial_view = tab_set
            .active()
            .map(|tab| tab.focus)
            .expect("a new window has an initial tab");
        let front_content = Some(front_content::FrontContent::Terminal {
            view: initial_view,
            session,
        });
        let active_terminal = Some(front_content::TerminalMirror {
            session,
            term,
            master,
            sink,
            ui_waiting,
        });
        Self::new_with_front(
            front_content,
            active_terminal,
            rows,
            cols,
            metrics,
            tabs,
            layouts,
            tab_set,
        )
    }

    /// Construct a terminal-free native/empty host. `front_content` may be
    /// absent only while restore is about to install its first native tab.
    fn new_native(
        front_content: Option<front_content::FrontContent>,
        rows: u16,
        cols: u16,
        metrics: MetricsView,
        tab_set: tab_model::TabSet,
    ) -> Self {
        debug_assert!(front_content.is_none_or(|front| front.native().is_some()));
        Self::new_with_front(
            front_content,
            None,
            rows,
            cols,
            metrics,
            TabIndex::new(0, 0),
            Vec::new(),
            tab_set,
        )
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "central initializer receives typed front capability plus canonical and compatibility projections"
    )]
