/// Locate and exec the release tool for `aterm ship …`. `aterm-release` is not in the app
/// bundle, so it is resolved from the publishing machine's repository in a fixed order,
/// with a plain message when the machine is not set up to publish. Never invokes a build
/// tool.
pub fn run_ship(rest: &[String]) -> i32 {
    let mut candidates: Vec<std::path::PathBuf> = Vec::new();
    // Beside this binary first: a publishing machine that has installed the tool wins over
    // any repo that merely happens to be the working directory.
    if let Ok(exe) = std::env::current_exe()
        && let Some(dir) = exe.parent()
    {
        candidates.push(dir.join("aterm-release"));
    }
    // Then the repo, walking up from the cwd so it works from any subdirectory.
    if let Ok(mut dir) = std::env::current_dir() {
        loop {
            if dir.join("Cargo.toml").is_file() {
                // `targo --unverified ship` builds it under `[profile.gate]`.
                candidates.push(dir.join("target/gate/aterm-release"));
                candidates.push(dir.join("target/release/aterm-release"));
                candidates.push(dir.join("target/debug/aterm-release"));
            }
            if !dir.pop() {
                break;
            }
        }
    }
    let Some(tool) = candidates.into_iter().find(|p| p.is_file()) else {
        crate::logging::stderr_line!("aterm ship: this machine is not set up to publish aterm.");
        crate::logging::stderr_line!(
            "aterm ship:   the release tool (`aterm-release`) ships with the SOURCE, not the \
             app — it is not something every install carries."
        );
        crate::logging::stderr_line!(
            "aterm ship:   from a checkout, build it once:  targo --unverified build --release \
             -p aterm-release"
        );
        return 1;
    };
    // TRANSPARENT, unlike every other child aterm starts: `aterm ship` stands in for
    // the release tool its caller ran (argv and stdio handed through), so ALL of the
    // caller's descriptors are the tool's — a make jobserver's pipe, a `3>` redirect —
    // whatever std this binary links (`aterm_uds::spawnfd::transparent`'s docs). Its
    // Windows console is still decided (`Console::Quiet`): a no-op from the
    // console `aterm ship` is typed in.
    match aterm_uds::spawnfd::transparent(&tool).args(rest).status() {
        Ok(status) => status.code().unwrap_or(1),
        Err(e) => {
            crate::logging::stderr_line!("aterm ship: could not run {}: {e}", tool.display());
            1
        }
    }
}

#[cfg(all(test, target_os = "macos"))]
#[path = "lib_macos_access_refresh_tests.rs"]
mod macos_access_refresh_tests;

#[cfg(all(test, target_os = "macos"))]
mod macos_access_lifetime_tests {
    use super::consent_card::{CardPhase, Marker, Verdict, WATCH_FOR};
    use super::control_privacy::ConsentState;
    use super::macos_access_refresh_tests::{access_row, grant_recorded, windowed};
    use aterm_containment::consent::{FdaProbe, FdaState, ProbeLabel};
    use std::time::Instant;

    #[test]
    fn pending_access_cannot_extend_any_waiting_phase() {
        let now = Instant::now();
        for phase in ["due", "watching"] {
            let mut app = windowed(FdaProbe::pending());
            assert!(app.consent_card.begin_deciding(now));
            assert!(app.consent_card.on_decided(&Verdict::Offer, now));
            if phase == "watching" {
                app.consent_card.on_raised(now);
            }
            app.tick_macos_access_card(now + WATCH_FOR);
            assert_eq!(app.consent_card.phase(), CardPhase::Settled, "{phase}");
            assert!(
                !access_row(&app) && !grant_recorded(&app),
                "an expired phase cannot offer or confirm"
            );
            assert_eq!(
                app.next_macos_access_card_deadline(now + WATCH_FOR),
                None,
                "an expired phase owns no timer"
            );
        }
    }

    #[test]
    fn timed_out_initial_probe_drops_its_deferred_marker_before_retry() {
        let now = Instant::now();
        let mut app = windowed(FdaProbe::pending());
        assert!(app.consent_card.begin_deciding(now));
        app.decide_macos_access_card(crate::consent_card::PendingDecision::launch(Some(
            Marker::Opened,
        )));
        assert_eq!(
            app.consent_card_host.pending,
            Some(crate::consent_card::PendingDecision::launch(Some(
                Marker::Opened
            )))
        );
        let deadline = app.consent_card.lifecycle_deadline().unwrap();
        assert!(app.next_macos_access_card_deadline(now).unwrap() <= deadline);
        app.tick_macos_access_card(deadline);
        assert_eq!(
            app.consent_card.phase(),
            CardPhase::Settled,
            "the retry starts on this wake and settles because this fixture has no worker proxy"
        );
        assert_eq!(app.consent_card_host.pending, None);
        assert!(!access_row(&app) && !grant_recorded(&app));
        // A worker from the expired attempt cannot turn the retained marker
        // into a success record while no decision is active.
        app.consent = ConsentState::with_cached_probe_for_test(FdaProbe {
            state: FdaState::Granted,
            label: ProbeLabel::OpenOk,
        });
        app.decide_macos_access_card(crate::consent_card::PendingDecision::launch(Some(
            Marker::Opened,
        )));
        assert_eq!(app.consent_card.phase(), CardPhase::Settled);
        assert_eq!(app.consent_card_host.pending, None);
        assert!(!grant_recorded(&app));
    }
}

