/// Every headless test process points the update crate's staging root at its own
/// scratch dir, once, so fixture apply records never reach the real per-user health
/// ledger. [`App::headless_for_test`] runs it.
///
/// Through the workspace's ONE blessed mutation helper — the exact shape the
/// `env_mutation` lint asks for — never a raw `set_var`. The lock serializes
/// this write against every other blessed mutator and against
/// `aterm_log::env::read`. BE HONEST ABOUT THE BOUND: it cannot serialize
/// against a bare `getenv` on another thread, and this variable's reader
/// (`seal_guard::updates_root`) is exactly that. What actually narrows the
/// window is `Once` plus position: one write, at the first harness
/// construction, before that harness's test can reach `Staging::resolve` — and
/// the tests that must never race it (`aterm_update::paths::Staging::scratch`)
/// already build their staging by hand for this very reason. This override is
/// deliberately process-permanent; set-and-restore would let a later test stage
/// under the REAL per-user ledger again. So the scratch is a PROCESS root
/// ([`test_scratch::process_root`]): removed when the process exits, and swept
/// by the next run when it was killed first.
///
/// Lock order: the `Once` takes `aterm_log::env`'s lock inside it, so nothing may reach
/// it while holding that lock; env-scoped tests go through [`test_env`], which primes
/// this first (`Once` → env lock).
#[cfg(any(test, feature = "bench-support"))]
pub(crate) fn prime_test_update_root() {
    prime_test_timing();
    static UPDATE_ROOT: std::sync::Once = std::sync::Once::new();
    UPDATE_ROOT.call_once(|| {
        let scratch = test_scratch::process_root("aterm-test-update-root-");
        aterm_log::env::set("ATERM_UPDATE_ROOT", &scratch);
    });
}

/// The env-scoped overrides for this crate's tests: `aterm_log::env`'s, with the
/// update-root `Once` primed before the lock ([`prime_test_update_root`]): a test
/// takes its env scopes here, never a direct `aterm_log::env::scoped`.
#[cfg(test)]
pub(crate) mod test_env {
    use std::ffi::OsStr;

    /// [`aterm_log::env::scoped`], primed.
    pub(crate) fn scoped<T>(
        key: impl AsRef<OsStr>,
        value: impl AsRef<OsStr>,
        body: impl FnOnce() -> T,
    ) -> T {
        super::prime_test_update_root();
        aterm_log::env::scoped(key, value, body)
    }

    /// [`aterm_log::env::scoped_unset`], primed.
    pub(crate) fn scoped_unset<T>(key: impl AsRef<OsStr>, body: impl FnOnce() -> T) -> T {
        super::prime_test_update_root();
        aterm_log::env::scoped_unset(key, body)
    }
}

/// The one capturing logger for this crate's tests: `aterm_log` keeps only the first
/// logger installed, so every test that reads logs installs this one
/// ([`test_log::install`]) and filters by a mark only it produces.
#[cfg(test)]
pub(crate) mod test_log {
    use std::cell::RefCell;
    use std::sync::{Mutex, OnceLock};

    type Observer = Box<dyn Fn(&aterm_log::Record<'_>)>;
    thread_local! {
        static OBSERVER: RefCell<Option<Observer>> = const { RefCell::new(None) };
    }

    /// One captured record: its level, its target and its rendered message.
    #[derive(Clone, Debug)]
    pub(crate) struct Captured {
        pub(crate) level: aterm_log::Level,
        pub(crate) target: String,
        pub(crate) message: String,
    }

    struct Capture;

    fn captured() -> &'static Mutex<Vec<Captured>> {
        static CAPTURED: OnceLock<Mutex<Vec<Captured>>> = OnceLock::new();
        CAPTURED.get_or_init(|| Mutex::new(Vec::new()))
    }

    impl aterm_log::Log for Capture {
        fn enabled(&self, _metadata: &aterm_log::Metadata) -> bool {
            true
        }
        fn log(&self, record: &aterm_log::Record<'_>) {
            OBSERVER.with(|observer| {
                if let Some(observe) = observer.borrow().as_ref() {
                    observe(record);
                }
            });
            captured()
                .lock()
                .unwrap_or_else(|p| p.into_inner())
                .push(Captured {
                    level: record.level(),
                    target: record.target().to_string(),
                    message: format!("{}", record.args()),
                });
        }
        fn flush(&self) {}
    }

    /// Install the capture — the first call in the process does; every later
    /// one finds it installed — with every level down to `Info` admitted.
    pub(crate) fn install() {
        static LOGGER: Capture = Capture;
        let _ = aterm_log::set_logger(&LOGGER);
        aterm_log::set_max_level(aterm_log::LevelFilter::Info);
    }

    /// Observe this thread's actual logger calls during `run`, restoring
    /// any outer observer even if it unwinds.
    pub(crate) fn observe<R>(
        observer: impl Fn(&aterm_log::Record<'_>) + 'static,
        run: impl FnOnce() -> R,
    ) -> R {
        struct Restore(Option<Observer>);
        impl Drop for Restore {
            fn drop(&mut self) {
                OBSERVER.with(|observer| observer.replace(self.0.take()));
            }
        }
        install();
        let _restore = Restore(OBSERVER.with(|slot| slot.replace(Some(Box::new(observer)))));
        run()
    }

    /// Every record captured so far whose message contains `mark`, oldest
    /// first.
    pub(crate) fn containing(mark: &str) -> Vec<Captured> {
        captured()
            .lock()
            .unwrap_or_else(|p| p.into_inner())
            .iter()
            .filter(|record| record.message.contains(mark))
            .cloned()
            .collect()
    }
}

/// Round eight of the update audit, #7 and its review: an update's relaunch of a
/// window started with `-e <cmd>` keeps the command for every tab it opens, and
/// its first session does not run it again.
#[cfg(test)]
mod relaunch_payload_tests {
    #[test]
    fn only_an_updates_relaunch_withholds_the_bootstrap_payload() {
        let payload = Some(vec![std::ffi::OsString::from("./deploy.sh")]);
        let mut factory = payload.clone();
        assert_eq!(super::withhold_bootstrap_payload(&mut factory, false), None);
        assert_eq!(
            factory, payload,
            "a person's launch runs it in its first tab"
        );
        let withheld = super::withhold_bootstrap_payload(&mut factory, true);
        assert_eq!(factory, None, "session 0 of a relaunch spawns without it");
        assert_eq!(withheld, payload, "…and it is kept to be put back");
    }
}

// A `clean { … }` island is Clean surface that only a Trust rustc can parse. A
// stock rustc (the cross cells of `verify cells`, the x86_64-apple-darwin
// compat slice) parses a cfg'd-out module's body all the same, so the island's
// module goes through this macro, which drops its tokens there and emits them
// unchanged under `cfg(clean_islands)` — the cfg `build.rs` sets when the
// compiler answers that it is Trust, so the island compiles in every Trust lane,
// RUSTFLAGS or not.
#[cfg(clean_islands)]
macro_rules! verify_island {
    ($($tt:tt)*) => {
        $($tt)*
    };
}

#[cfg(not(clean_islands))]
macro_rules! verify_island {
    ($($tt:tt)*) => {};
}

verify_island! {
    mod about_to_wait_preview_proofs {
        // Every Settings presentation view belongs to the process-singleton
        // `AppKind::Settings` instance (`instance_exists`). Therefore, when no
        // `AppKind::Settings` instance exists (`Not instance_exists`), no window
        // can have a Settings preview (`Not window_has_preview`), and skipping
        // the per-window preview scan yields the identical `None` animation.
        clean {
            section AboutToWaitPreviewGate
            theorem NoSettingsInstanceImpliesNoWindowPreview :
                forall (instance_exists window_has_preview : Prop)
                    (h_dep : window_has_preview -> instance_exists),
                    Not instance_exists ->
                    Not window_has_preview :=
                fun (instance_exists window_has_preview : Prop)
                    (h_dep : window_has_preview -> instance_exists)
                    (h_no_inst : Not instance_exists) =>
                    fun (h_win : window_has_preview) =>
                        h_no_inst (h_dep h_win)
            end AboutToWaitPreviewGate
        }
    }
}
